/*
Circular Blinking Beats - Svenofnine
https://www.shadertoy.com/view/M3KczK
*/

#define PI 3.141592653   //589793238462643383279502884197169399375105820974944592307816406286208998628034825
#define max_ring 32.

const 
uint[] pattern = uint[12] (
  15255086u,                   // "0" =(14u<<20) + (17u<<15) + (17u<<10) + (17u<<5) + 14u;
  12718222u,                   // "1" =(12u<<20) +  (4u<<15) +  (4u<<10) +  (4u<<5) + 14u;
  31504927u,                   // "2" =(30u<<20) +  (1u<<15) + (14u<<10) + (16u<<5) + 31u;
  31504446u,                   // "3" =(30u<<20) +  (1u<<15) + (14u<<10) +  (1u<<5) + 30u;
  19496002u,                   // "4" =(18u<<20) + (18u<<15) + (31u<<10) +  (2u<<5) +  2u;
  33060926u,                   // "5" =(31u<<20) + (16u<<15) + (30u<<10) +  (1u<<5) + 30u;
  15235630u,                   // "6" =(14u<<20) + (16u<<15) + (30u<<10) + (17u<<5) + 14u;
  32540808u,                   // "7" =(31u<<20) +  (1u<<15) +  (2u<<10) +  (4u<<5) +  8u;
  15252014u,                   // "8" =(14u<<20) + (17u<<15) + (14u<<10) + (17u<<5) + 14u;
  15252526u,                   // "9" =(14u<<20) + (17u<<15) + (15u<<10) +  (1u<<5) + 14u;
  4u,                          // "." =4u;
  31744u                       // "-" =31u<<10;
);

// first published in https://www.shadertoy.com/view/4XyyWz
// writes the value of an integer in a grid, every character in a square 1x1
// uv = frag coordinate, ofs = position bottom left corner of number, n = number to be written
float write_uint(vec2 uv, vec2 ofs, uint n) {
    float xc = 0.;                                  // x-cursor - position in the string
    int id = -1;                                    // id of the character which will be written
    uint p = 1000000000u;                             // power - the weight of the biggest digit
    while(n<p)p/=10u;                           // abs() is the reason why this function can't handle -2147483648 !!
    // d = coordinates of the character hit by uv   
    vec2 d = floor(uv-ofs);                         // first we need just the bottom left of each place        
    // the digits...
    while( (p>1u) && (id==-1) ) {
        if( d.x==xc) id=int(float(n/p));            // set character "0".."9" at cursor 
        n = n%p; p /= 10u;                           //    get rid of the biggest digit, shorten power by one "0", 
        xc++;                                       //    next character in string
    }
    if( (id==-1) && (d.x==xc)) id=int(float(n));  
    // create the digit at cursor position
    uint bits = id==-1 ? 0u : pattern[id];
    // o = output value
    float o = .0;
    d = uv - ofs - vec2(d.x,.0);                    // d = coordinates within that one character
    // between which four dot matrix pixels of the character does uv go through?
    uint ax = uint(5.-d.x*6.25);                     
    uint ay = uint(d.y*6.25 - 1.);
    if(ay<5u)
        for(uint y=ay; y<=ay+1u; y++)
            for(uint x=ax; x<=min(ax+1u,4u); x++)
              if( ( bits & ( 1u<<(y*5u+x) ) ) > 0u)
                  o += smoothstep( .16, .03, distance( d, .16 * vec2( uvec2(5u-x, 1u+y) ) ) );
    return o;
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   // vec2 uv = vec2(fragCoord.x/iResolution.y-0.5*iResolution.x/iResolution.y, fragCoord.y/iResolution.y-0.5);
    // vec2 uv = vec2((fragCoord.x-0.5*iResolution.x)/iResolution.y, (fragCoord.y-0.5*iResolution.y)/iResolution.y);
    // vec2 uv = vec2(fragCoord.x-.5*iResolution.x, fragCoord.y-.5*iResolution.y)/iResolution.y;
    vec2 uv = (fragCoord - .5*iResolution.xy) / iResolution.y;

    float dist = .0; 

    dist = max_ring*length(uv);                      // original
    //alternatives:
    //dist = 32.*pow(length(uv), 1.+ ((iFrame%32<8) ? 1. : 0.)*0.2*( sin( float(iFrame%8)/4.*PI )));  // jumping beat
    //dist = 32.*pow(length(uv), 0.2);          // a tunnel
    //dist = 32.*pow(length(uv*uv*uv),0.33);    // squared

    //int n = 126;   // = 3 *
     uint n = uint(iFrame)/8u;  // max n = 4294967295

    float 
        ring_nr = floor(dist),
        angle = atan( uv.y, uv.x) + 2.*PI*fract(iTime*0.01)*(2.*float(int(ring_nr)%2*2-1)),
        ring_blink = ( mod(floor(float(n)),ring_nr+1.) == ring_nr) ? 1. : 0.,
        ring_elements = ( sin(angle*ring_nr)  > 0.) ? 2. : 1.,
        black_gaps = smoothstep(0., 0.1, abs(sin(angle*ring_nr)));

    vec3 
        col = vec3( abs(sin(dist*PI)) ) * ( ring_blink*ring_elements == 1. ? vec3(1.) : vec3(0.3) ) * black_gaps +
    smoothstep(1., 0., dist ) +
    .5*vec3( write_uint(uv*10., vec2(-0.5*ceil(log(float(n))/log(10.)),-4.), n) );

    // Output to screen
    fragColor = vec4(col,1.0);
}
